S from maplemonk.ka_gs_sku_mrp_cogs qualify row_number() over (partition by lower(commonskucode), start_date, end_date order by 1) =1 ) mrp on lower(BC.commonsku) = lower(mrp.commonskucode) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(BC.ORDER_STATUS) = LOWER(ShipMap.shipping_status) UNION ALL SELECT NULL AS customer_id, \'INDIA\' AS region, UPPER(u.marketplace) AS shop_name, UPPER(u.marketplace) AS marketplace, UPPER(u.marketplace) AS channel, UPPER(u.marketplace) AS source, u.order_id AS order_id, u.reference_code AS reference_code, u.phone AS phone, u.name AS name, u.email AS email, CAST(u.shipping_last_update_date AS TIMESTAMP) AS shipping_last_update_date, u.SKU AS sku, u.PRODUCT_ID AS product_id, UPPER(u.product_name) AS product_name, u.currency AS currency, UPPER(u.city) AS city, UPPER(u.state) AS state, UPPER(u.order_status) AS order_status, u.order_Date AS order_date, CAST(u.order_Date AS DATETIME) AS order_time, u.suborder_quantity AS quantity, IFNULL(u.selling_price,0) - IFNULL(u.tax,0) + IFNULL(u.discount,0) AS gross_sales_before_tax, u.discount AS discount, u.tax AS tax, u.shipping_price AS shipping_price, u.selling_price AS selling_price, UPPER(u.order_status) AS oms_order_status, UPPER(u.shipping_status) AS shipping_status, UPPER(shipmap.final_shipping_status) AS final_shipping_status, u.saleorderitemcode AS saleorderitemcode, u.sales_order_item_id AS sales_order_item_id, u.awb AS awb, NULL AS payment_gateway, u.payment_mode AS payment_mode, UPPER(u.Courier) AS courier, CAST(u.Dispatch_Date AS DATETIME) AS dispatch_date, CAST(u.Delivered_date AS DATETIME) AS delivered_date, CASE WHEN LOWER(shipmap.final_shipping_status) = \'delivered\' THEN 1 ELSE 0 END AS delivered_status, u.Return_flag AS return_flag, CASE WHEN u.Return_flag = 1 THEN CAST(u.suborder_quantity AS INT64) END AS returned_quantity, CASE WHEN u.Return_flag = 1 THEN u.selling_price END AS returned_sales, u.cancelled_quantity AS cancelled_quantity, u.NEW_CUSTOMER_FLAG AS new_customer_flag, NULL AS acquisition_product, EXTRACT(DAY FROM u.days_in_shipment) AS days_in_shipment, NULL AS acquisition_date, u.SKU AS sku_code, UPPER(u.product_name_final) AS product_name_final, UPPER(u.product_category) AS product_category, UPPER(u.product_sub_category) AS product_sub_category, NULL AS commonsku, UPPER(u.warehouse_name) AS warehouse, u.pincode AS pincode, NULL AS source_pincode FROM maplemonk.KA_UNICOMMERCE_FACT_ITEMS u LEFT JOIN ( SELECT shipping_status, mapped_status AS final_shipping_status FROM maplemonk.shipment_status_mapping ) shipmap ON LOWER(u.shipping_status) = LOWER(shipmap.shipping_status) WHERE LOWER(u.marketplace) IN ( \'flipkart\',\'nykaa_com\',\'pharmeasy\',\'snapdeal\' ) ; CREATE OR REPLACE TABLE maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM maplemonk.KA_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM maplemonk.KA_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; drop table `maplemonk.KA_sales_consolidated`; CREATE OR REPLACE TABLE maplemonk.KA_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM maplemonk.KA_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email; ALTER TABLE maplemonk.KA_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE maplemonk.KA_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE maplemonk.KA_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.KA_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE maplemonk.KA_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE maplemonk.KA_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.KA_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE maplemonk.KA_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM maplemonk.KA_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE maplemonk.KA_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE maplemonk.KA_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM maplemonk.KA_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE maplemonk.KA_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; Create Or Replace table maplemonk.KA_sales_consolidated as WITH Sales AS ( SELECT customer_id_final AS MM_CUSTOMER_ID, Order_id, min(DATE(Order_Date)) AS ORDER_DATE, SUM(IFNULL(SELLING_PRICE, 0)) AS Pre_TOTAL_SALES_INR FROM `MapleMonk.KA_sales_consolidated` where customer_id_final is not null GROUP BY 1, 2 ), ordered AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY MM_CUSTOMER_ID ORDER BY ORDER_DATE) AS order_rank, LAG(ORDER_DATE) OVER (PARTITION BY MM_CUSTOMER_ID ORDER BY ORDER_DATE) AS prev_order_date, MIN(ORDER_DATE) OVER (PARTITION BY MM_CUSTOMER_ID) AS Min_Order_Date, COUNT(order_id) OVER (PARTITION BY MM_CUSTOMER_ID ORDER BY ORDER_DATE, ORDER_ID ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS total_orders_till_date, sum(ifnull(Pre_TOTAL_SALES_INR,0)) OVER (PARTITION BY MM_CUSTOMER_ID ORDER BY ORDER_DATE, ORDER_ID ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS TOTAL_SALES_INR FROM Sales ), with_date_diffs AS ( SELECT *, DATE_DIFF(ORDER_DATE, prev_order_date, DAY) AS DAYS_SINCE_LAST_PURCHASE, CASE WHEN total_orders_till_date = 0 THEN NULL ELSE DATE_DIFF(ORDER_DATE, Min_Order_Date , DAY) / total_orders_till_date END AS AVG_DAYS_BETWEEN_PURCHASES, FROM ordered ) select SC.*,DAYS_SINCE_LAST_PURCHASE,AVG_DAYS_BETWEEN_PURCHASES, TOTAL_SALES_INR as TOTAL_SALES_Till_Date from maplemonk.KA_sales_consolidated sc left join with_date_diffs dd on sc.ORDER_ID = dd.ORDER_ID; CREATE TABLE IF NOT EXISTS maplemonk.KA_unicommerce_returns_intermediate ( MARKETPLACE STRING, SOURCE STRING, ORDER_ID STRING, REFERENCE_CODE STRING, PHONE STRING, NAME STRING, EMAIL STRING, ORDER_DATE TIMESTAMP, RETURN_DISPLAYCODE STRING, RETURN_STATUS STRING, INVENTORY_RECEIVED_DATE TIMESTAMP, RETURN_COMPLETE_DATE TIMESTAMP, RETURN_INVOICE_DISPLAY_CODE STRING, RETURN_COURIER STRING, RETURN_PROVIDER_SHIPPING_STATUS STRING, RETURN_TRACKING_NUMBER STRING, RETURN_TYPE STRING, sale_order_item_code STRING, ITEMSKU STRING, ITEM_NAME STRING, INVENTORY_TYPE STRING ); CREATE OR REPLACE TABLE maplemonk.KA_unicommerce_returns_fact_items AS SELECT IFNULL(FE.channel, \'NA\') AS Marketing_CHANNEL, FE.commonsku, FE.quantity AS RETURNED_QUANTITY, FE.selling_price AS TOTAL_RETURN_AMOUNT, FE.tax AS RETURN_TAX, FE.selling_price - FE.tax AS RETURN_AMOUNT_WITHOUT_TAX, GA4.channel_Category, FR.* FROM (select * from maplemonk.KA_unicommerce_returns_intermediate where return_display_code is not null) FR LEFT JOIN ( SELECT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, SALEORDERITEMCODE, commonsku, channel, Source, SUM(quantity) AS quantity, SUM(selling_price) AS Selling_price, SUM(tax) AS tax FROM maplemonk.KA_sales_consolidated GROUP BY REFERENCE_CODE, SALEORDERITEMCODE, channel, Source, commonsku ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE AND FR.sale_order_item_code = FE.SALEORDERITEMCODE LEFT Join ( select transactionid ,Final_Source ,Channel ,channel_category from maplemonk.KA_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) = 1 ) GA4 on FR.reference_code = GA4.transactionid ; CREATE OR REPLACE TABLE maplemonk.KA_returns_consolidated AS SELECT UPPER(fr.MARKETPLACE) AS Marketplace, cast(RETURN_COMPLETE_DATE as datetime) AS RETURN_DATE, UPPER(Marketing_CHANNEL) AS Marketing_channel, SUM(RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(TOTAL_RETURN_AMOUNT) AS TOTAL_RETURN_AMOUNT, SUM(RETURN_TAX) AS TOTAL_RETURN_TAX, SUM(RETURN_AMOUNT_WITHOUT_TAX) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM maplemonk.KA_unicommerce_returns_fact_items fr GROUP BY fr.Marketplace, RETURN_COMPLETE_DATE, Marketing_channel; Create Or Replace Table `maplemonk.KA_sales_consolidated_partition_Temporary` as select * from `maplemonk.KA_sales_consolidated`; drop table `maplemonk.KA_sales_consolidated`; CREATE OR REPLACE TABLE `maplemonk.KA_sales_consolidated` PARTITION BY date(order_date) AS select * from `maplemonk.KA_sales_consolidated_partition_Temporary`;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

